// Package matrix reads internal/authz/testdata/matrix.yaml, the authz
// conformance matrix (plan §5.6-3), for the Go and OpenFGA runners. The
// file is generated by docs/faz0/tarama/pairs.py; its header documents the
// fields.
package matrix

import (
	"fmt"
	"os"
	"regexp"
	"sort"
	"strings"
)

// Engines of a case.
const (
	// EngineBoth: the case runs on the Go evaluator and on OpenFGA.
	EngineBoth = "go+openfga"
	// EngineGoOnly: a rule outside the model (prefilter, attribute,
	// ownership, Scope); it runs only once that Go rule exists.
	EngineGoOnly = "go_only"
	// EngineSkip: the case does not run (reason in the pair).
	EngineSkip = "skip"
)

// Case is one row of the matrix.
type Case struct {
	ID      string
	Pair    string
	Action  string // "<type>.<action>"
	Subject string // "anonymous" or "user:<id>"
	Object  string // "<type>:<id>"
	Expect  string // "allow" or "deny"
	Basis   string // key of Matrix.Basis; allow rows
	Conceal *bool  // deny rows
	Engine  string // EngineBoth, EngineGoOnly or EngineSkip
	Note    string
}

// Allowed reports whether the expected decision is allow.
func (c *Case) Allowed() bool { return c.Expect == "allow" }

// Matrix is the parsed matrix.
type Matrix struct {
	// Basis maps a basis key to its description, which names the granting
	// relation in parentheses: "atamanın işçisi (job_assignment#worker)".
	Basis map[string]string
	// Actions maps "<type>.<action>" to "type#relation", "Scope(...)" or
	// "go:<rule>".
	Actions map[string]string
	// Tuples are the fixture tuples, "object#relation@user".
	Tuples []string
	Cases  []Case
}

// Load reads and parses the matrix file.
func Load(path string) (*Matrix, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("matrix: %w", err)
	}
	return Parse(string(data))
}

// Parse parses the matrix document.
func Parse(src string) (*Matrix, error) {
	doc, err := parseYAML(src)
	if err != nil {
		return nil, fmt.Errorf("matrix: %w", err)
	}
	root, ok := doc.(map[string]any)
	if !ok {
		return nil, fmt.Errorf("matrix: the document is not a mapping")
	}
	m := &Matrix{}
	if m.Basis, err = stringMap(root, "basis"); err != nil {
		return nil, err
	}
	if m.Actions, err = stringMap(root, "actions"); err != nil {
		return nil, err
	}
	fixtures, ok := root["fixtures"].(map[string]any)
	if !ok {
		return nil, fmt.Errorf("matrix: fixtures is not a mapping")
	}
	tuples, ok := fixtures["tuples"].([]any)
	if !ok {
		return nil, fmt.Errorf("matrix: fixtures.tuples is not a sequence")
	}
	for i, t := range tuples {
		s, ok := t.(string)
		if !ok {
			return nil, fmt.Errorf("matrix: fixtures.tuples[%d] is not a string", i)
		}
		m.Tuples = append(m.Tuples, s)
	}
	cases, ok := root["cases"].([]any)
	if !ok {
		return nil, fmt.Errorf("matrix: cases is not a sequence")
	}
	seen := map[string]bool{}
	for i, raw := range cases {
		c, err := parseCase(raw)
		if err != nil {
			return nil, fmt.Errorf("matrix: cases[%d]: %w", i, err)
		}
		if seen[c.ID] {
			return nil, fmt.Errorf("matrix: duplicate case %s", c.ID)
		}
		seen[c.ID] = true
		if _, ok := m.Actions[c.Action]; !ok {
			return nil, fmt.Errorf("matrix: %s: action %q is not in actions", c.ID, c.Action)
		}
		if c.Basis != "" {
			if _, ok := m.Basis[c.Basis]; !ok {
				return nil, fmt.Errorf("matrix: %s: basis %q is not in basis", c.ID, c.Basis)
			}
		}
		m.Cases = append(m.Cases, c)
	}
	return m, nil
}

// Relation returns the model relation of an action, or false when the
// action maps to a Go rule or a Scope.
func (m *Matrix) Relation(action string) (objectType, relation string, ok bool) {
	target := m.Actions[action]
	if strings.HasPrefix(target, "go:") || strings.HasPrefix(target, "Scope(") {
		return "", "", false
	}
	return strings.Cut(target, "#")
}

// basisRelation matches "(type#relation)" in a basis description.
var basisRelation = regexp.MustCompile(`\(([a-z_]+#[a-z_]+)\)`)

// BasisRelation returns the relation a basis key names, "type#relation",
// or false when the description names none (public, owner, ...).
func (m *Matrix) BasisRelation(key string) (string, bool) {
	sub := basisRelation.FindStringSubmatch(m.Basis[key])
	if sub == nil {
		return "", false
	}
	return sub[1], true
}

func parseCase(raw any) (Case, error) {
	f, ok := raw.(map[string]any)
	if !ok {
		return Case{}, fmt.Errorf("not a mapping")
	}
	keys := make([]string, 0, len(f))
	for k := range f {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	known := map[string]bool{
		"id": true, "pair": true, "action": true, "subject": true, "object": true, "expect": true,
		"basis": true, "conceal": true, "java": true, "java_conceal": true, "engine": true,
		"note": true, "inventory": true, "source": true,
	}
	for _, k := range keys {
		if !known[k] {
			return Case{}, fmt.Errorf("unknown field %q", k)
		}
	}
	var c Case
	var err error
	for _, s := range []struct {
		key      string
		dst      *string
		required bool
	}{
		{"id", &c.ID, true}, {"pair", &c.Pair, true}, {"action", &c.Action, true},
		{"subject", &c.Subject, true}, {"object", &c.Object, true}, {"expect", &c.Expect, true},
		{"basis", &c.Basis, false}, {"note", &c.Note, false},
	} {
		if *s.dst, err = str(f, s.key, s.required); err != nil {
			return Case{}, err
		}
	}
	if c.Expect != "allow" && c.Expect != "deny" {
		return Case{}, fmt.Errorf("%s: expect %q", c.ID, c.Expect)
	}
	if v, ok := f["conceal"]; ok {
		b, ok := v.(bool)
		if !ok {
			return Case{}, fmt.Errorf("%s: conceal is not a boolean", c.ID)
		}
		c.Conceal = &b
	}
	if c.Expect == "deny" && c.Conceal == nil {
		return Case{}, fmt.Errorf("%s: a deny row needs conceal", c.ID)
	}
	switch e := f["engine"].(type) {
	case string:
		c.Engine = e
	case []any:
		parts := make([]string, 0, len(e))
		for _, p := range e {
			s, ok := p.(string)
			if !ok {
				return Case{}, fmt.Errorf("%s: engine list holds a non-string", c.ID)
			}
			parts = append(parts, s)
		}
		c.Engine = strings.Join(parts, "+")
	}
	if c.Engine != EngineBoth && c.Engine != EngineGoOnly && c.Engine != EngineSkip {
		return Case{}, fmt.Errorf("%s: engine %q", c.ID, c.Engine)
	}
	return c, nil
}

func str(f map[string]any, key string, required bool) (string, error) {
	v, ok := f[key]
	if !ok || v == nil {
		if required {
			return "", fmt.Errorf("missing %q", key)
		}
		return "", nil
	}
	s, ok := v.(string)
	if !ok {
		return "", fmt.Errorf("%q is not a string", key)
	}
	return s, nil
}

func stringMap(root map[string]any, key string) (map[string]string, error) {
	raw, ok := root[key].(map[string]any)
	if !ok {
		return nil, fmt.Errorf("matrix: %s is not a mapping", key)
	}
	out := make(map[string]string, len(raw))
	for k, v := range raw {
		s, ok := v.(string)
		if !ok {
			return nil, fmt.Errorf("matrix: %s.%s is not a string", key, k)
		}
		out[k] = s
	}
	return out, nil
}
